import java.util.*;

public class Main {
    int maximum69Number(int num) {
        char[] digits = Integer.toString(num).toCharArray();  // break the number into individual characters
        int best = num;                                       // start with no change as a valid candidate
        for (int i = 0; i < digits.length; i++) {
            if (digits[i] == '6') {                            // try flipping this particular 6
                char[] candidate = digits.clone();             // work on a fresh copy so other 6s stay untouched
                candidate[i] = '9';
                best = Math.max(best, Integer.parseInt(new String(candidate))); // rebuild and compare
            }
        }
        return best;                                            // the largest candidate seen, or num itself
    }

    public static void main(String[] args) {
        int num = 9669;
        Main solution = new Main();
        System.out.println(solution.maximum69Number(num));
    }
}

