public class Main {
    int maximum69Number(int num) {
        int placeValue = 1;
        int temp = num;
        while (temp > 0) {                  // find the largest place value present, no string built at all
            placeValue *= 10;
            temp /= 10;
        }
        placeValue /= 10;                    // step back one, now it matches the leading digit's place
        while (placeValue > 0) {
            int digit = (num / placeValue) % 10;   // extract just this one digit, most significant first
            if (digit == 6) {
                return num + 3 * placeValue;         // 9 minus 6 is 3, this jumps straight to the flipped value
            }
            placeValue /= 10;
        }
        return num;                                  // no 6 found, the number is already maximal
    }

    public static void main(String[] args) {
        int num = 9669;
        Main solution = new Main();
        System.out.println(solution.maximum69Number(num));
    }
}

